GN['tr.es'] = {
A1: [
 {t:'Pronombres, el verbo «ser/estar» y var / yok',
  b:`<p>Los pronombres son [[ben]] (yo), [[sen]] (tú), [[o]] (él / ella / ello), [[biz]] (nosotros), [[siz]] (vosotros / usted), [[onlar]] (ellos). El turco no tiene género: [[o]] significa él y ella.</p><p>No existe un verbo «ser / estar» independiente: se añade una terminación corta a la palabra: [[öğrenciyim]] = soy estudiante.</p><div class="tblwrap"><table><tr><th>pronombre</th><th>terminación</th><th>ejemplo</th></tr><tr><td>ben</td><td>-(y)im</td><td>[[yorgunum]]</td></tr><tr><td>sen</td><td>-sin</td><td>[[yorgunsun]]</td></tr><tr><td>o</td><td>—</td><td>[[yorgun]]</td></tr><tr><td>biz</td><td>-(y)iz</td><td>[[yorgunuz]]</td></tr><tr><td>siz</td><td>-siniz</td><td>[[yorgunsunuz]]</td></tr><tr><td>onlar</td><td>-(ler)</td><td>[[yorgunlar]]</td></tr></table></div><p>[[var]] = hay, [[yok]] = no hay. «Tengo» se dice con posesión + var: [[Benim bir arabam var.]] = Tengo un coche.</p><p class="tip">La vocal de la terminación se adapta a la palabra (armonía vocálica): -im, -ım, -um, -üm.</p>`,
  ex:['Soy estudiante.','Eres muy amable.','Él tiene un coche.','No hay leche en casa.'],
  q:['«Estoy cansado»:','«Tenemos un gato»:']},
 {t:'La armonía vocálica y el plural -ler / -lar',
  b:`<p>Las terminaciones turcas cambian su vocal según la última vocal de la palabra. Es la armonía vocálica, la clave de todo el idioma.</p><p>El plural es [[-ler]] después de e, i, ö, ü y [[-lar]] después de a, ı, o, u: [[ev]] → [[evler]] (casas), [[kitap]] → [[kitaplar]] (libros).</p><div class="tblwrap"><table><tr><th>última vocal</th><th>2 formas</th><th>4 formas</th></tr><tr><td>a, ı</td><td>-lar, -da</td><td>-ı</td></tr><tr><td>o, u</td><td>-lar, -da</td><td>-u</td></tr><tr><td>e, i</td><td>-ler, -de</td><td>-i</td></tr><tr><td>ö, ü</td><td>-ler, -de</td><td>-ü</td></tr></table></div><p class="tip">Después de un número el sustantivo va en singular: [[iki kitap]] = dos libros.</p>`,
  ex:['Los libros están en la mesa.','Los niños juegan en el jardín.','Las casas son muy grandes.','¿Dónde están los bolígrafos?'],
  q:['«libros»:','«casas»:']},
 {t:'El presente continuo -iyor',
  b:`<p>Para decir lo que pasa ahora o lo que haces normalmente, añade [[-iyor]] a la raíz del verbo y después la terminación de persona: [[geliyorum]] = vengo / estoy viniendo.</p><div class="tblwrap"><table><tr><th>persona</th><th>gelmek (venir)</th><th>konuşmak (hablar)</th></tr><tr><td>ben</td><td>[[geliyorum]]</td><td>[[konuşuyorum]]</td></tr><tr><td>sen</td><td>[[geliyorsun]]</td><td>[[konuşuyorsun]]</td></tr><tr><td>o</td><td>[[geliyor]]</td><td>[[konuşuyor]]</td></tr><tr><td>biz</td><td>[[geliyoruz]]</td><td>[[konuşuyoruz]]</td></tr><tr><td>siz</td><td>[[geliyorsunuz]]</td><td>[[konuşuyorsunuz]]</td></tr><tr><td>onlar</td><td>[[geliyorlar]]</td><td>[[konuşuyorlar]]</td></tr></table></div><p class="tip">La -a / -e final de la raíz desaparece: [[yemek]] → [[yiyorum]], [[beklemek]] → [[bekliyorum]].</p>`,
  ex:['Vivo en Estambul.','¿Hablas turco?','Estamos tomando café.','Ellos trabajan mucho.'],
  q:['«tú hablas»:','«nosotros venimos»:']},
 {t:'Negación y preguntas: -me, değil, mi',
  b:`<p>El verbo se niega con [[-me]] / [[-ma]] tras la raíz: [[konuşmuyorum]] = no hablo. Los sustantivos y adjetivos usan [[değil]]: [[O doktor değil.]] = Él no es médico.</p><p>Las preguntas de sí/no llevan la partícula [[mi]] (mı, mu, mü), escrita aparte detrás de la palabra preguntada: [[Çay seviyor musun?]] = ¿Te gusta el té?</p><p class="tip">La terminación de persona pasa a mi: [[Yorgun musun?]] = ¿Estás cansado?</p>`,
  ex:['No hablo inglés.','Él no es médico.','¿Te gusta el té?','¿Vivís aquí?'],
  q:['«No como carne»:','«Él no es profesor»:']}
],
A2: [
 {t:'Los casos de lugar: -de, -e, -den',
  b:`<p>Dónde está algo, adónde va y de dónde viene se expresa con terminaciones, no con preposiciones.</p><div class="tblwrap"><table><tr><th>caso</th><th>terminación</th><th>ejemplo</th></tr><tr><td>en (locativo)</td><td>-de / -da (-te / -ta)</td><td>[[evde]] en casa, [[mutfakta]] en la cocina</td></tr><tr><td>a (dativo)</td><td>-(y)e / -(y)a</td><td>[[okula]] a la escuela, [[eve]] a casa</td></tr><tr><td>de (ablativo)</td><td>-den / -dan (-ten / -tan)</td><td>[[Ankara’dan]] de Ankara</td></tr></table></div><p class="tip">Tras p, ç, t, k, f, h, s, ş la d se convierte en t: [[kitapta]], [[sokaktan]]. Con nombres propios se escribe apóstrofo: [[İstanbul’a]].</p>`,
  ex:['Mi madre está en la cocina.','Voy a la escuela.','Este autobús viene de Ankara.','Saqué el libro de la bolsa.'],
  q:['«Voy a la escuela»:','«Vengo de Turquía»:']},
 {t:'Los posesivos y el objeto definido -i',
  b:`<p>«Mi, tu, su» son terminaciones del sustantivo: [[evim]] mi casa, [[evin]] tu casa, [[evi]] su casa, [[evimiz]] nuestra casa, [[eviniz]] vuestra casa, [[evleri]] su casa (de ellos). Para insistir se añade el pronombre: [[benim evim]].</p><p>«El hermano de Ali» = [[Ali’nin kardeşi]]: el poseedor lleva -in y lo poseído -i.</p><p>El objeto directo definido lleva [[-i]] (ı, u, ü): [[Bu kitabı okudum.]] = Leí este libro. Un objeto general no lleva nada: [[Kitap okudum.]] = Leí (libros).</p>`,
  ex:['Mi casa es grande.','¿Dónde está tu coche?','Leí este libro.','Mi hermano se llama Ali.'],
  q:['«Vi esta película»:','«mi madre»:']},
 {t:'El pasado -di',
  b:`<p>Añade [[-di]] (dı, du, dü, ti, tı, tu, tü) a la raíz para acciones terminadas que viste o hiciste: [[geldim]] vine, [[geldin]], [[geldi]], [[geldik]], [[geldiniz]], [[geldiler]].</p><p>Negación: [[gelmedim]] no vine. Pregunta: [[Geldin mi?]] ¿Viniste?</p><p>Con sustantivos y adjetivos -di significa «era / estaba»: [[Hava soğuktu.]] = Hacía frío.</p>`,
  ex:['Ayer fui al cine.','¿Habéis desayunado?','No llegamos tarde.','Hacía mucho frío.'],
  q:['«Ayer leí un libro»:','«Ellos vinieron»:']},
 {t:'El futuro -ecek y el imperativo',
  b:`<p>El futuro es [[-ecek]] / [[-acak]]: [[geleceğim]] vendré, [[geleceksin]], [[gelecek]], [[geleceğiz]], [[geleceksiniz]], [[gelecekler]]. Ante vocal la k pasa a ğ.</p><p>El imperativo de «tú» es la raíz sola: [[Gel!]] ¡Ven! [[Kapat!]] ¡Cierra! La forma cortés o plural añade -in: [[Gelin!]], [[Bekleyin, lütfen.]]</p><p class="tip">Futuro negativo: [[gelmeyeceğim]] = no vendré.</p>`,
  ex:['Mañana me levantaré temprano.','¿Qué harás por la tarde?','Cierra la puerta, por favor.','Esperen un poco, por favor.'],
  q:['«Mañana te llamaré»:','«No vendremos»:']}
],
B1: [
 {t:'El aoristo: hábitos y verdades generales',
  b:`<p>El aoristo ([[geniş zaman]]) se usa para hábitos, hechos generales, ofrecimientos y promesas: [[Her sabah kahve içerim.]] = Tomo café cada mañana.</p><p>Su terminación es [[-r]] tras vocal ([[okur]]), [[-er]] / [[-ar]] en la mayoría de verbos de una sílaba ([[yazar]], [[içer]]) e [[-ir]] en raíces más largas ([[çalışır]]). Hay excepciones: [[gelir]], [[alır]], [[bilir]].</p><p>Negación: [[içmem]] no bebo, [[içmezsin]], [[içmez]], [[içmeyiz]], [[içmezsiniz]], [[içmezler]].</p><p class="tip">Una pregunta en aoristo es un ofrecimiento cortés: [[Çay içer misiniz?]] = ¿Quiere un té?</p>`,
  ex:['Tomo café cada mañana.','En invierno nieva.','No fumo.'],
  q:['«Voy andando al trabajo cada día»:','«No como carne»:']},
 {t:'Capacidad -ebil y obligación -meli',
  b:`<p>«Poder» es [[-ebil]] / [[-abil]] tras la raíz: [[yüzebilirim]] = sé nadar, [[gelebilir misin?]] = ¿puedes venir? «No poder» es [[-eme]] / [[-ama]]: [[yüzemem]] = no sé nadar.</p><p>«Deber / tener que» es [[-meli]] / [[-malı]]: [[çalışmalısın]] = deberías estudiar. También se dice [[lazım]] o [[gerek]]: [[Gitmem lazım.]] = Tengo que irme.</p>`,
  ex:['Puedo hablar turco.','¿Puedes venir mañana?','Deberías estudiar más.'],
  q:['«Sé nadar»:','«Deberías acostarte temprano»:']},
 {t:'El pasado referido -miş',
  b:`<p>[[-miş]] (mış, muş, müş) cuenta hechos pasados que no viste: te los contaron o ves el resultado: [[Ali İzmir’e gitmiş.]] = (Dicen que) Ali se fue a Esmirna.</p><p>También expresa sorpresa ante algo que acabas de descubrir: [[Bu film çok güzelmiş!]] = ¡Pues esta película es muy buena!</p><p class="tip">Compara: [[geldi]] (vi que vino) y [[gelmiş]] (por lo visto vino).</p>`,
  ex:['(Dicen que) Ali se fue ayer a Esmirna.','Resulta que esta película es muy buena.','Resulta que la puerta estaba abierta.'],
  q:['«(Dicen que) Ahmet se casó»:','«(Resulta que) hace frío»:']}
],
B2: [
 {t:'Condicionales con -se',
  b:`<p>La condición real usa aoristo + [[-se]]: [[Zamanım olursa sana yardım ederim.]] = Si tengo tiempo, te ayudo.</p><p>La condición irreal pone [[-se]] directamente en la raíz y el resultado lleva [[-irdi]]: [[Param olsa bu evi alırdım.]] = Si tuviera dinero, compraría esta casa. En pasado: [[olsaydı … alırdım]].</p><p>[[Keşke]] + -se expresa un deseo: [[Keşke daha erken gelseydin.]] = Ojalá hubieras venido antes.</p>`,
  ex:['Si tengo tiempo, te ayudo.','Si hubiera tenido dinero, habría comprado esta casa.','Ojalá hubieras venido antes.'],
  q:['«Si llueve, nos quedamos en casa»:','«Si lo hubiera sabido, lo habría dicho»:']},
 {t:'Participios: -en y -diği',
  b:`<p>El turco no tiene «que» relativo. La oración relativa va delante del sustantivo y el verbo se convierte en participio.</p><p>Si el sustantivo realiza la acción: [[-en]] / [[-an]]: [[oynayan çocuk]] = el niño que juega.</p><p>Si es el objeto o el lugar: [[-diği]] + posesivo: [[okuduğum kitap]] = el libro que leí, [[yaşadığımız şehir]] = la ciudad donde vivimos.</p>`,
  ex:['El niño que juega en el jardín es mi hijo.','El libro que leí ayer era muy interesante.','La ciudad donde vivimos está muy concurrida.'],
  q:['«la mujer que ríe»:','«la película que vi»:']},
 {t:'Sustantivos verbales: -mek, -me y -diği için',
  b:`<p>[[-mek]] / [[-mak]] es el infinitivo del diccionario: [[Yüzmek istiyorum.]] = Quiero nadar. Con terminaciones de caso se usa [[-me]] / [[-ma]]: [[Yüzmeyi severim.]] = Me gusta nadar.</p><p>[[-diği]] + posesivo convierte una frase en sustantivo: [[Onun geleceğini biliyorum.]] = Sé que vendrá.</p><p>[[-diği için]] = porque: [[Geç kaldığım için özür dilerim.]] = Perdón por llegar tarde.</p>`,
  ex:['Me encanta nadar.','Perdón por llegar tarde.','Sé que él vendrá.'],
  q:['«Me gusta leer libros»:','«No vino porque estaba enfermo»:']}
],
C1: [
 {t:'La pasiva y la causativa',
  b:`<p>La pasiva añade [[-il]] (tras la mayoría de consonantes), [[-in]] (tras l y vocales) o [[-n]]: [[yapmak]] → [[yapıldı]] (fue construido), [[göndermek]] → [[gönderildi]] (fue enviado), [[okumak]] → [[okundu]].</p><p>La causativa («hacer que alguien haga») añade [[-dir]] / [[-t]]: [[Saçımı kestirdim.]] = Me corté el pelo (en la peluquería). [[Arabamı yıkattım.]] = Hice lavar mi coche.</p>`,
  ex:['Esta casa fue construida en 1950.','La carta se envió ayer.','Me corté el pelo en la peluquería.'],
  q:['«La puerta fue abierta»:','«Hice lavar mi coche»:']},
 {t:'Gerundios: -ince, -ken, -erek',
  b:`<p>Los gerundios unen dos acciones sin «cuando» ni «y».</p><div class="tblwrap"><table><tr><th>terminación</th><th>significado</th><th>ejemplo</th></tr><tr><td>[[-ince]]</td><td>cuando, en cuanto</td><td>[[Eve gelince]] = cuando llegue a casa</td></tr><tr><td>[[-ken]]</td><td>mientras</td><td>[[Yemek yerken]] = mientras como</td></tr><tr><td>[[-erek]]</td><td>-ando / -iendo</td><td>[[Gülerek]] = riendo</td></tr><tr><td>[[-ip]]</td><td>y (luego)</td><td>[[Oturup bekledi.]] = se sentó y esperó</td></tr></table></div>`,
  ex:['Cuando llegue a casa, te llamo.','No veo la tele mientras como.','Entró en la habitación riendo.'],
  q:['«Al oír la noticia, se alegró mucho»:','«Vino corriendo»:']}
],
C2: [
 {t:'Gerundios avanzados: -dikçe, -meden, -mişçesine',
  b:`<p>[[-dikçe]] = cuanto más… / cada vez que: [[Okudukça öğreniyorsun.]] = Cuanto más lees, más aprendes.</p><p>[[-meden]] = sin hacer: [[Hiçbir şey söylemeden çıktı.]] = Salió sin decir nada. La variante formal es [[-meksizin]].</p><p>[[-mişçesine]] / [[-casına]] = como si: [[Her şeyi biliyormuşçasına konuşuyor.]] = Habla como si lo supiera todo.</p>`,
  ex:['Cuanto más lees, más aprendes.','Salió sin decir nada.','Habla como si lo supiera todo.'],
  q:['«Cuanto más trabajas, más éxito tienes»:','«Se fue sin avisar a nadie»:']},
 {t:'Estilo escrito formal: -mektedir y -miştir',
  b:`<p>En noticias, informes y textos académicos el presente suele escribirse con [[-mektedir]] / [[-maktadır]] en lugar de -iyor: [[Fiyatlar artmaktadır.]] = Los precios están subiendo.</p><p>[[-dir]] / [[-tır]] da a la frase un tono oficial y seguro: [[Bu konu daha önce tartışılmıştır.]] = Este tema ya se ha discutido.</p><p class="tip">En el habla, -dir suele significar «probablemente»: [[Yorgundur.]] = Debe de estar cansado.</p>`,
  ex:['La reunión empieza a las diez.','Este tema ya se ha discutido.','Los resultados parecen positivos.'],
  q:['«El proyecto se inició en 2020» (formal):','«Los precios están subiendo» (formal):']}
]
};
